  SCEN.L = { name: "큰 평원의 부족 연합", star: 5, world: true, title: "대추장", tag: ["world", "낯선 만남"], like: "1600~1890년, 아메리카 원주민이 유럽에서 온 사람들과 만났을 때와 비슷해요. ('인디언'은 콜럼버스가 이 땅을 인도로 잘못 알고 붙인 이름이라, 오늘날에는 '아메리카 원주민'이라고 불러요.)", text: "숲과 큰 평원에서 여러 부족이 버펄로를 사냥하고 옥수수를 기르며 살아요. 그런데 바다 건너 낯선 사람들이 배를 타고 오기 시작했어요. 땅과 전통을 지키며 살아남아야 해요.",
    st: { kp: 36, har: 32, ppl: 46, gold: 40, def: 38, cul: 64 }, done: [],
    only: () => POL.filter((p) => p.scen && p.scen.includes("L")).map((p) => p.id),
    labels: () => ({ kp: ["추장의 힘", "長", "대추장의 말이 부족들에게 미치는 힘"], har: ["부족 연합", "和", "여러 부족이 한마음으로 뭉친 정도"], ppl: ["부족민", "民", "부족 사람들이 대추장을 믿고 따르는 마음"], gold: ["식량", "食", "버펄로 고기·옥수수·가죽 같은 먹을거리와 물자"], def: ["전사", "戰", "부족을 지키는 전사들의 힘"], cul: ["전통", "傳", "말과 이야기, 춤과 지혜를 지키는 힘"] }),
    driftText: ["전사들이 다치고 늙어 감", "부족 사람들이 조금씩 지침", "추장의 말이 조금씩 약해짐"],
    econ: () => ({ normal: ["평소대로 사냥하고 거두기", "평소처럼 사냥하고 옥수수를 거두었어요."], more: ["사냥을 크게 늘리기", "사냥을 늘려 식량은 넉넉해졌지만 부족 사람들이 지쳤어요."], market: ["교역소에서 모피 팔기", "모피를 팔아 쇠냄비와 옷감을 얻었어요. 모피를 더 얻으려고 부족끼리 다투기도 했어요."], thrift: ["추장 집안부터 아끼기", "추장 집안이 먼저 아꼈어요. 부족 사람들이 고마워했지만 추장의 위엄은 조금 줄었어요."], less: ["부족민 몫 늘리기", "사냥한 고기를 부족 사람들에게 더 많이 나눴어요."], voyage: ["먼 부족과 큰 교역 (모험)", "먼 부족과의 교역이 대성공! 귀한 조개구슬과 물자를 가득 얻었어요.", "교역 길에서 도둑을 만나 물건을 빼앗겼어요."] }) };
  Object.assign(EV, {
    l1: { h: "舟", title: "바다를 건너온 큰 배", text: () => "커다란 돛을 단 배에서 낯선 옷을 입은 사람들이 내렸어요(1607년). 그들은 먹을 것이 모자라 굶주리고 있어요. 대추장의 딸은 그들을 도와주자고 해요(포카혼타스 이야기처럼).",
      choices: () => [
        C("옥수수를 나눠 주고 친구가 된다", () => { S.flags.friend = true; return SR({ har: 3, ppl: 2, gold: -6, cul: 2 }, "굶주린 낯선 사람들이 옥수수로 겨울을 넘겼어요. 그들은 고마워하며 쇠도끼를 선물했어요.", [-0.4, -0.2, 0.5], "낯선 사람들이 옥수수를 처음 먹고 '이게 무슨 맛이냐' 하더니 한 바구니를 다 비웠다."); }),
        C("우리 땅에 머물지 말고 떠나라고 경고한다", () => SR({ kp: 6, def: 2, ppl: -2 }, "낯선 사람들은 잠시 물러났지만, 바다 건너에서 배가 계속 오고 있었어요.", [0.6, 0.4, 0], "대추장이 떠나라 경고하니, 낯선 사람들이 고개를 끄덕이고는 다음 날 배를 두 척 더 데려왔다.")),
        C("쇠도끼·냄비와 모피를 바꾸는 장사를 한다", () => { S.flags.trade = true; return SR({ gold: 8, cul: -3 }, "쇠냄비와 도끼는 정말 편리했어요. 하지만 사람들은 점점 옛 도구 만드는 법을 잊어 갔어요.", [0.1, 0, 0], "쇠냄비를 처음 써 본 할머니가 냄비를 두드리며 북처럼 노래하였다."); }),
        GB("그들을 부족 연합에 받아들여 함께 산다", 0.4, () => SR({ har: 6, cul: 4, def: 4 }, "낯선 사람들이 우리말을 배우고 함께 사냥했어요. 서로의 지혜를 나누었어요.", [-0.5, -0.3, 0.4], "낯선 사람이 우리 춤을 배우니, 발이 꼬여 모닥불 주위를 거꾸로 돌았다."), () => SR({ ppl: -6, gold: -4 }, "그들은 약속을 어기고 땅에 울타리를 치기 시작했어요.", [-0.5, -0.3, 0.4], "낯선 사람들이 함께 살자 하더니, 다음 날 아침 땅에 말뚝을 박고 이름을 적었다.", FAILX), "잘되면 서로 돕고, 안되면 땅을 빼앗기기 시작해요."),
      ] },
    l2: { h: "病", title: "처음 보는 병 (천연두)", base: () => ({ ppl: has("lmed") ? -5 : -11, def: -5 }), text: () => "바다 건너온 사람들과 만난 마을마다 처음 보는 병(천연두)이 번지고 있어요. 원주민은 이 병을 이겨 낼 힘이 없어 많은 사람이 쓰러지고 있어요." + (has("lmed") ? " 약초 치료사들 덕분에 피해가 조금 줄었어요." : ""),
      choices: () => [
        C("약초와 땀 움막으로 치료한다", () => SR({ cul: 4, ppl: 3, gold: -4 }, "치료사들이 밤낮으로 환자를 돌보았어요. 마음은 위로했지만 병은 계속 번졌어요.", [0, -0.3, 0.5], "땀 움막에서 나온 환자가 '병은 그대로인데 땀은 다 뺐다' 하였다.")),
        C("병든 마을과 떨어져 멀리 옮겨 간다", () => SR({ ppl: 5, gold: -8, har: -2 }, "건강한 사람들이 멀리 옮겨 가 병을 피했어요. 하지만 사냥터와 밭을 잃었어요.", [0, 0, 0.3], "부족이 짐을 싸서 떠나니, 개들이 먼저 앞장서 길을 안내하였다.")),
        C("낯선 사람들과의 만남을 모두 끊는다", () => SR({ ppl: 6, gold: -6, kp: 3 }, "병은 덜 퍼졌지만 쇠도구와 옷감을 얻을 길이 끊겼어요.", [0.4, 0, 0.2], "낯선 사람이 찾아오자 망보던 아이가 '병 들고 오지 마세요!' 하고 외쳤다.")),
        GB("치료사들이 모여 큰 치유 의식을 올린다", 0.3, () => SR({ ppl: 8, har: 5 }, "의식이 끝나자 병이 잦아들기 시작했어요. 부족 사람들이 다시 힘을 냈어요.", [-0.2, -0.3, 0.4], "치유 의식의 북소리가 사흘 밤낮 울리니, 병이 북소리에 질려 달아났다 하더라."), () => SR({ ppl: -4, cul: 2 }, "의식을 위해 사람들이 모이자 병이 더 퍼졌어요.", [-0.2, -0.3, 0.4], "치유 의식에 사람이 너무 많이 모여 병도 함께 모였다.", FAILX), "잘되면 마음이 하나로 모이고, 안되면 병이 더 퍼져요."),
      ] },
    l3: { h: "馬", title: "말과 총", text: () => "스페인 사람들이 데려온 말이 큰 평원으로 퍼졌어요(1680년대). 말을 타면 버펄로를 훨씬 쉽게 사냥할 수 있어요. 낯선 상인들은 총도 팔겠다고 해요.",
      choices: () => [
        C("말 타는 법을 익혀 버펄로 사냥꾼이 된다", () => { S.flags.horse = true; return SR({ gold: 8, def: 6, cul: -2 }, "말을 탄 사냥꾼들이 바람처럼 평원을 달렸어요. 버펄로 고기가 넉넉해졌어요.", [0.2, 0.6, 0.2], "처음 말을 탄 전사가 말 위에서 거꾸로 앉아 달렸으나, 사냥은 제일 잘하였다."); }),
        C("모피를 주고 총을 사들인다", () => { S.flags.guns = true; return SR({ def: 10, gold: -7 }, "전사들이 총을 들었어요. 하지만 화약과 총알은 낯선 상인에게서만 살 수 있었어요.", [0.4, 0.9, 0], "총을 처음 쏜 전사가 소리에 놀라 총을 던지고 활을 집어 들었다."); }),
        C("옛 방식대로 걸어서 사냥하고 농사짓는다", () => SR({ cul: 6, har: 2, gold: -2 }, "조상의 방식을 지켰어요. 이야기와 노래가 그대로 이어졌어요.", [-0.3, -0.5, 0.2], "걸어서 사냥하던 노인이 말 탄 젊은이를 보고 '버펄로는 걸어서 잡아야 제맛'이라 하였다.")),
        GB("야생마 떼를 길들이는 큰 사냥을 한다", 0.5, () => { S.flags.horse = true; return SR({ def: 8, gold: 6, kp: 3 }, "수백 마리의 야생마를 길들였어요! 우리 부족이 평원 최고의 기마 부족이 되었어요.", [0.4, 0.6, 0], "야생마 떼를 길들이니, 우두머리 말이 대추장에게 고개를 숙였다 한다."); }, () => SR({ def: -4, ppl: -3 }, "야생마 떼가 날뛰며 마을을 휩쓸고 달아났어요.", [0.4, 0.6, 0], "야생마 떼가 마을을 지나가니, 천막 세 채가 말 등에 실려 함께 떠났다.", FAILX), "성공하면 전사와 식량이 함께 늘어요."),
      ] },
    l4: { h: "約", title: "땅을 팔라는 종이", text: () => "낯선 사람들이 종이 한 장을 내밀며 '이 땅을 사겠다'고 해요(1750년대). 원주민에게 땅은 누군가의 것이 아니라 모두가 함께 쓰는 어머니 같은 곳이에요.",
      choices: () => [
        C("선물을 받고 땅의 일부를 내준다", () => { S.flags.sold = true; return SR({ gold: 10, har: -6, ppl: -4 }, "선물은 받았지만, 그들은 내준 땅보다 훨씬 넓은 곳에 울타리를 쳤어요.", [0, 0, -0.3], "땅을 내주고 받은 구슬을 세어 보니, 사냥터 하나에 구슬 스무 개였다."); }),
        C("땅은 팔 수 없다고 거절한다", () => SR({ kp: 4, ppl: 4, def: -4 }, "'하늘과 땅을 어떻게 사고팔 수 있나요?' 거절하자 낯선 사람들과 사이가 나빠졌어요.", [0.5, 0, 0.3], "대추장이 '바람도 팔 거냐' 하고 물으니, 낯선 사람이 한참 생각하다 대답을 못 하였다.")),
        C("경계를 정하는 약속(조약)을 맺는다", () => { S.flags.treaty = true; return SR({ def: 3, gold: 4, har: 2, kp: -3 }, "경계를 정하고 서로 넘지 않기로 약속했어요. 하지만 실제 역사에서는 이런 약속이 여러 번 깨졌어요.", [-0.2, 0, 0], "조약 문서에 서명하니, 낯선 사람들의 글씨는 꼬불꼬불하고 대추장의 서명은 독수리 그림이었다."); }),
        GB("그들의 글을 배워 조약 내용을 꼼꼼히 따진다", 0.5, () => SR({ cul: 6, gold: 6, kp: 3 }, "조약 속 숨은 속임수를 찾아내 고쳤어요! 낯선 사람들이 깜짝 놀랐어요.", [0.3, -0.4, 0], "대추장이 조약의 작은 글씨를 찾아내니, 낯선 사람이 안경을 고쳐 쓰며 땀을 흘렸다."), () => SR({ har: -4, gold: -2 }, "글을 아무리 따져도 그들은 자기들 뜻대로 우겼어요.", [0.3, -0.4, 0], "조약을 따졌으나, 낯선 사람이 '글이 그렇게 쓰여 있다'만 되풀이하였다.", FAILX), "성공하면 땅도 지키고 이익도 얻어요."),
      ] },
    l5: { h: "盟", title: "모든 부족이 하나로", text: () => "젊은 지도자(테쿰세처럼)가 '모든 부족이 하나로 뭉쳐야 땅을 지킬 수 있다'며 여러 부족을 찾아다녀요(1810년대). 하지만 오래 다퉈 온 부족들도 있어요.",
      choices: () => [
        C("모든 부족 대표가 모이는 큰 회의를 연다", () => SR({ har: 10, kp: -4, gold: -3 }, "모닥불 둘레에 수십 부족의 대표가 모였어요. 평화의 담뱃대가 한 바퀴 돌았어요.", [-0.8, 0, 0.2], "부족 회의에서 모두 한마디씩 하니, 해가 세 번 뜨고 나서야 회의가 끝났다.")),
        C("젊은 지도자에게 전사들을 맡긴다", () => { S.flags.tecumseh = true; return SR({ def: 10, kp: -5 }, "젊은 지도자가 이끄는 전사들이 하나로 뭉쳤어요. 사람들은 대추장보다 그를 더 따르기 시작했어요.", [-0.5, 0.8, 0], "젊은 지도자가 연설하니, 늙은 전사들까지 창을 높이 들었다."); }),
        C("부족의 일은 각 부족이 정하게 둔다", () => SR({ ppl: 4, cul: 2, har: -5 }, "각 부족은 자유로웠지만, 힘을 하나로 모으지는 못했어요.", [-0.2, 0, 0.4], "부족마다 따로 정하니, 같은 날 열두 부족이 열두 방향으로 사냥을 떠났다.")),
        GB("바다 건너 다른 큰 나라(영국)와 손잡고 함께 싸운다", 0.4, () => SR({ def: 10, gold: 6 }, "강한 나라와 손잡고 땅을 지켜 냈어요!", [0.2, 0.7, 0], "영국 장교가 우리 전사들과 나란히 서니, 키 큰 깃털 모자가 더 눈에 띄었다."), () => SR({ def: -8, har: -4 }, "함께 싸우던 나라가 전쟁이 끝나자 약속을 잊었어요(1812년 전쟁처럼).", [0.2, 0.7, 0], "전쟁이 끝나자 영국 장교가 배를 타고 떠나며 손만 흔들었다.", FAILX), "실제 역사에서는 약속이 지켜지지 않았어요."),
      ] },
    l6: { h: "字", title: "부족의 글자", text: () => "한 체로키 사람(세쿼이아)이 12년 동안 연구해 부족의 말을 적을 수 있는 글자를 만들었어요(1821년). 세종의 훈민정음처럼 누구나 며칠 만에 배울 수 있대요!",
      choices: () => [
        C("글자를 온 부족에 가르친다", () => { S.flags.script = true; if (!has("lscript")) S.done.push({ id: "lscript", turn: S.turn, ok: true, by: "event" }); return SR({ cul: 12, ppl: 6, gold: -4 }, "몇 해 만에 부족 사람 대부분이 글을 읽고 쓰게 되었어요!", [0, -0.8, 0.8], "글자를 배운 아이들이 천막마다 낙서를 하니, 대추장 천막에도 '추장님 최고'라 쓰여 있었다."); }, "'부족 글자 만들기' 정책을 한 것과 같아요."),
        C("부족 신문을 펴낸다", () => SR({ cul: 6, kp: 4, har: 3, gold: -6 }, "부족의 글자와 영어로 함께 쓴 신문이 나왔어요(체로키 피닉스처럼). 바깥세상에 우리 목소리가 전해졌어요.", [0.2, -0.6, 0.3], "부족 신문 첫 호가 나오니, 노인들이 거꾸로 들고 그림만 보았다.")),
        C("말로 전하는 전통이 더 소중하다며 미룬다", () => SR({ har: 3, cul: -2 }, "옛 방식을 지켰지만 귀한 기회를 놓쳤어요.", [-0.3, 0, 0], "이야기꾼 할머니가 '글로 쓰면 이야기가 재미없어진다' 하였다.")),
        GB("글자로 부족의 법과 헌법을 만든다", 0.6, () => SR({ kp: 8, cul: 6, har: 4 }, "체로키 부족처럼 글로 쓴 헌법과 법원을 만들었어요(1827년). 바깥 사람들도 우리를 하나의 나라로 보기 시작했어요.", [0.5, -0.5, -0.4], "헌법을 만드니, 아이들이 '헌법 제1조, 간식은 나눠 먹는다'를 외우고 다녔다."), () => SR({ har: -6, kp: -2 }, "어떤 법을 넣을지 다투다 회의가 깨졌어요.", [0.5, -0.5, -0.4], "헌법 회의에서 다툼이 나니, 글자를 쓰던 붓이 모두 부러졌다.", FAILX), "성공하면 추장의 힘과 전통이 함께 커져요."),
      ] },
    l7: { h: "淚", title: "눈물의 길", base: () => ({ ppl: -8, gold: -4 }), text: () => "미국 정부가 '원주민 이주법'(1830)을 만들어, 조상 대대로 살던 땅을 떠나 먼 서쪽으로 옮겨 가라고 해요. 군인들이 총을 들고 마을을 둘러쌌어요(1838년).",
      choices: () => [
        GB("법정에서 땅을 지킬 권리를 끝까지 주장한다", Math.min(0.5, 0.22 + (S.flags.script ? 0.15 : 0) + (S.st.cul >= 60 ? 0.1 : 0) + (S.flags.courtWon ? 0.1 : 0)), () => { S.flags.stayed = true; return SR({ kp: 8, ppl: 8, def: 2 }, "역사와 달리 법원의 판결이 지켜졌어요! 조상의 땅에 남을 수 있게 되었어요.", [0.3, -0.5, 0.4], "법원 판결이 지켜지니, 부족 사람들이 법원 앞에서 사흘 동안 춤을 추었다."); }, () => { S.flags.trail = true; return SR({ kp: 2, ppl: -6, gold: -8 }, "법원은 원주민 편을 들었지만(1832년 판결처럼), 대통령은 판결을 따르지 않았어요. 결국 떠나야 했어요.", [0.3, -0.5, 0.4], "법원에서 이겼으나, 대통령이 판결문을 서랍에 넣고 열쇠를 잠갔다.", FAILX); }, "부족 글자가 있거나 전통이 60 이상이면 확률이 올라요."),
        C("싸우지 않고 서쪽으로 떠난다", () => { S.flags.trail = true; return SR({ ppl: -8, gold: -8, har: 4 }, "천 킬로미터가 넘는 길을 걸으며 많은 사람이 추위와 병으로 쓰러졌어요. 이 길을 '눈물의 길'이라고 불러요.", [-0.3, 0, 0.3], "눈물의 길을 걸으니, 길가의 나무들도 잎을 떨구었다.", FAILX); }),
        C("늪지대로 숨어 끝까지 버틴다 (세미놀처럼)", () => S.st.def >= 45 ? SR({ def: -4, kp: 6, ppl: 3 }, "늪지대를 잘 아는 전사들이 군인들을 막아 냈어요. 세미놀 부족처럼 끝내 떠나지 않았어요.", [0.5, 0.8, 0], "군인들이 늪에 빠져 장화를 잃으니, 악어가 장화를 물고 갔다.") : SR({ def: -10, ppl: -6 }, "전사가 모자라 늪지대도 지켜 내지 못했어요.", [0.5, 0.8, 0], "늪으로 숨었으나 모기가 군인보다 무서웠다.", FAILX), "전사가 45 이상이어야 버틸 수 있어요."),
        C("일부는 남고 일부는 떠나 부족의 맥을 잇는다", () => SR({ har: -6, ppl: -3, cul: 3, gold: -4 }, "부족이 둘로 나뉘었어요. 산속에 남은 사람들은 훗날 그 땅에서 다시 부족을 일으켰어요.", [0, 0, 0.2], "남는 사람과 떠나는 사람이 서로 이야기 한 자락씩을 나눠 가졌다.")),
      ] },
    l8: { h: "牛", title: "사라지는 버펄로", base: () => ({ gold: has("lhunt") ? -5 : -11, ppl: -3 }), text: () => "철도가 큰 평원을 가로지르고, 사냥꾼들이 기차 창문 밖으로 버펄로를 마구 쏘아 죽이고 있어요(1860~1870년대). 수천만 마리였던 버펄로가 빠르게 사라지고 있어요." + (has("lhunt") ? " 사냥 규칙을 지켜 온 덕분에 우리 땅에는 아직 버펄로가 조금 남아 있어요." : ""),
      choices: () => [
        C("남은 버펄로를 지키는 사냥 규칙을 더 엄하게 한다", () => SR({ cul: 4, har: 3, gold: -2 }, "새끼 밴 버펄로는 잡지 않고, 필요한 만큼만 사냥했어요.", [-0.2, -0.3, 0.3], "사냥 규칙이 엄해지니, 버펄로들이 우리 땅에만 오면 느긋하게 풀을 뜯었다.")),
        C("옥수수·콩·호박 농사를 늘린다 (세 자매 농사)", () => SR({ gold: 6, ppl: 2, cul: -2 }, "옥수수 줄기를 콩이 타고 오르고, 호박잎이 땅을 덮는 '세 자매 농사'로 먹을거리를 마련했어요.", [0, 0, 0.3], "세 자매 농사를 지으니, 옥수수가 콩에게 '그만 좀 올라와' 하였다 한다.")),
        GB("철도를 막아 사냥꾼을 몰아낸다", 0.35, () => SR({ def: 4, gold: 6, kp: 4 }, "철도를 막자 사냥꾼들이 평원을 떠났어요!", [0.5, 0.8, 0], "전사들이 기찻길에 버티고 서니, 기차가 멈춰 서서 기적만 울렸다."), () => SR({ def: -12, ppl: -4 }, "군대가 몰려와 전사들이 크게 다쳤어요.", [0.5, 0.8, 0], "기찻길을 막았으나, 기차에서 군인들이 줄줄이 내렸다.", FAILX), "실패하면 전사를 크게 잃어요."),
        C("정부가 주는 식량을 받으러 보호 구역으로 들어간다", () => { S.flags.reservation = true; return SR({ gold: 10, kp: -8, cul: -5 }, "굶주림은 피했지만, 좁은 보호 구역 안에서 사냥도, 옛 의식도 마음대로 할 수 없게 되었어요.", [-0.5, 0, 0.2], "보호 구역 식량 배급 줄에서 대추장이 맨 뒤에 섰다. 그날 줄이 유난히 길었다.", FAILX); }),
      ] },
    l9: { h: "戰", title: "검은 언덕의 결전", text: () => { const m = lPow(); return `금을 찾는 사람들이 성스러운 검은 언덕(블랙힐스)으로 몰려들자, 시팅 불과 크레이지 호스 같은 지도자들이 전사들을 모았어요(1876년). 미국 기병대가 다가오고 있어요. 우리 전사의 힘은 약 ${m}, 기병대는 약 60이에요.`; },
      choices: () => [
        C("모든 부족이 함께 맞서 싸운다", () => { const m = lPow(); if (m >= 60) { S.flags.warWon = true; return SR({ def: 4, kp: 8, ppl: 6 }, `리틀빅혼 전투처럼 기병대를 크게 무찔렀어요! 우리 ${m} : 적 60. 하지만 실제 역사에서는 이 승리 뒤 미국이 더 많은 군대를 보냈어요.`, [0.4, 1, 0.2], "기병대 대장이 말에서 내려 모자를 벗으니, 그 모자는 지금도 이야기 속에 남아 있다."); } S.flags.warLost = true; return SR({ def: -14, ppl: -8 }, `기병대의 총과 대포를 막지 못했어요. 우리 ${m} : 적 60`, [0.4, 1, 0.2], "전사들이 쓰러진 들판에 독수리 깃털만 바람에 날렸다.", FAILX); }, "말·총·젊은 지도자·부족 연합이 힘을 더해요."),
        C("흩어져 북쪽 나라(캐나다)로 피한다", () => SR({ def: -2, har: -6, ppl: 2 }, "시팅 불처럼 북쪽으로 피했어요. 목숨은 지켰지만 고향과 멀어졌어요.", [-0.2, 0, 0.3], "북쪽으로 가니 눈이 어찌나 깊던지 말들이 눈 위로 귀만 내밀고 걸었다.")),
        C("땅을 지키는 협상을 끝까지 이어 간다", () => SR({ kp: -4, gold: 5, cul: 2 }, "협상은 길어졌고, 땅은 조금씩 줄었어요. 하지만 싸움 없이 사람들을 지켰어요.", [-0.4, -0.3, 0.2], "협상이 길어지니, 양쪽 대표가 서로 상대의 수염 모양을 다 외웠다.")),
        GB("검은 언덕 골짜기로 기병대를 꾀어 들인다", 0.5, () => SR({ def: 8, kp: 5 }, "골짜기에 들어선 기병대가 길을 잃고 물러갔어요!", [0.4, 0.8, 0], "골짜기에서 길을 잃은 기병대가 같은 바위를 세 번 지나갔다."), () => SR({ def: -10, kp: -4 }, "작전이 들통나 전사들이 포위되었어요.", [0.4, 0.8, 0], "골짜기 작전이 들통나니, 전사들이 바위 뒤에서 서로 '네가 말했지' 하고 눈짓하였다.", FAILX), "잘되면 피해 없이 이기고, 안되면 크게 져요."),
      ] },
    l10: { h: "七", title: "일곱 세대 뒤의 아이들", text: () => "1890년, 많은 땅을 잃었지만 부족은 아직 살아 있어요. 원주민 어른들은 '무엇을 정할 때는 일곱 세대 뒤의 아이들을 생각하라'고 가르쳐요. 다음 세대에게 무엇을 남길까요?",
      choices: () => [
        C("우리말과 이야기, 춤을 아이들에게 가르친다", () => { S.flags.keepCulture = true; return SR({ cul: 10, ppl: 4 }, "아이들이 할머니에게 이야기를 듣고 춤을 배웠어요. 오늘날에도 원주민들은 큰 모임(파우와우)에서 그 춤을 춰요.", [-0.3, -0.6, 0.5], "아이들이 춤을 배우니, 할아버지가 젊은 시절 춤을 추다 허리를 붙잡았다."); }),
        C("새 세상의 학교에서 배우되 뿌리를 잊지 않게 한다", () => { S.flags.bothWays = true; return SR({ cul: 4, kp: 4, gold: 4 }, "아이들이 두 세상의 말을 모두 배웠어요. 훗날 그들이 부족을 대표해 목소리를 냈어요.", [0.2, -0.5, 0.2], "두 나라 말을 배운 아이가 통역을 하니, 어른들 싸움이 절반으로 줄었다."); }),
        C("땅을 되찾는 싸움을 법정에서 이어 가게 한다", () => { S.flags.courts = true; return SR({ kp: 6, har: 4, gold: -3 }, "후손들이 법정에서 땅을 되찾는 싸움을 이어 갔어요. (실제로 1980년 미국 대법원은 검은 언덕을 억울하게 빼앗았다고 판결했어요. 부족은 보상금 대신 땅을 돌려 달라며 지금도 받지 않고 있어요.)", [0.4, -0.3, 0], "후손들이 법정에 서니, 판사가 조상들의 조약 문서를 읽다 안경을 닦았다."); }),
      ] },
  });
  const lPow = () => S.st.def + (S.flags.horse ? 6 : 0) + (S.flags.guns ? 6 : 0) + (S.flags.tecumseh ? 4 : 0) + (has("lhorse") ? 4 : 0) + (S.flags.ally ? 6 : 0) + Math.round(S.st.har * 0.1);
